        int(part) if part is not None else 0 for part in ints
    )
    if seconds is None:
        second_value: float = 0
    elif "." in seconds:
        second_value = float(seconds)
    else:
        second_value = int(seconds)
    return Duration(years, months, weeks, days, hours, minutes, second_value)


